{
  "root": "root_column",
  "state": {
    "flights": [
      {
        "id": "ana",
        "airline": "ANA",
        "type": "Direct",
        "logo": "../assets/r_000264_01_logo_ana_official.svg",
        "fare": "GBP 1,035",
        "departure": "19:00",
        "arrival": "17:55+1",
        "travelTime": "13h 55m",
